'use strict';class TimelineTemplates{static TimelineToc({index:a,mediaTypeFilter:b,metadataDates:d,year:c,month:e,day:f}){return`
        ${0===a||0<a&&d[a-1].year!==c?`
            <strong>${c}</strong>
            <div class='list-group'>
        `:""}
    
        ${0<a&&d[a-1].year===c&&d[a-1].month===e?`
                <a style="display:none" id="offcanvas_${c}-${e}-${f}" class="list-group-item list-group-item-action${0===a?" active":""}" href="#${c}-${e}-${f}"></a>
        `:`
                <a id="offcanvas_${c}-${e}-${f}" class="list-group-item list-group-item-action${0===a?" active":""}" href="#${c}-${e}-${f}">${(new Date(c,e-1,f)).format("mmm yyyy")}</a>
        `}
        
                <script type="text/javascript"${0<shashin.nonce.length?` nonce="${shashin.nonce}"`:""}>
                    $("#offcanvas_${c}-${e}-${f}").on("click", function (e) {
                        e.preventDefault();
                        timelineSettings.jumpFromTimelineToc(e,"${c}-${e}-${f}","${b}")
                    });
                </script>
    
        ${0<a&&a<d.length-1&&d[a+1].year!==c?"\n            </div>\n            <br>\n        ":""}
    `}static MapLinks({metadata:a,placeNameDisplayName:b,queryParamDates:d}){return`
        <a href="/map?lat=${a.lat}&lng=${a.lng}${d}" target="_blank" style="text-decoration: none;"><span class="bi-geo-alt-fill" style="font-size:1.0rem;"></span>${b}</a>&nbsp;<a href="https://www.google.com/maps/search/?api=1&query=${a.lat}%2C${a.lng}" target="_blank" class="bi-google" style="text-decoration: none;"></a>
    `}static HeaderThumbnail({metadata:a}){return`
        <img loading="lazy" src="${encodeURI(a.thumbnailUrlCentered)}" height="100" width="100">
    `}static BatchHeaderThumbnail({thumbnailImage:a,title:b}){return`
        <img loading="lazy" src="${a}" height="75" width="75" data-bs-toggle="tooltip" data-bs-placement="top" title="${b}">
    `}static TimelinePreLoadGalleryHeader({metadata:a,placeNameHeaders:b,listHtml:d}){return`
        ${null===a.year||null===a.month||null===a.day?'\n        <span class="dateContainer" id="container_undated">\n        <br id="brundated">\n        <section class="scrollspy" id="undated"><p><strong class="undatedTimelinePhotos p-1">Undated</strong></p></section>\n        <div class="row image-group-padding" id="rowundated">\n        ':`
        <span class="dateContainer" id="container_${a.year}-${a.month}-${a.day}">
        <br id="br${a.year}-${a.month}-${a.day}">
        <section class="scrollspy" id="${a.year}-${a.month}-${a.day}"><div class="mb-3"><strong class="dateHeading p-1">${Util.getDateString(a.year,a.month,a.day)}</strong>
        ${1===b.length?'<span class="text-muted"><a class="link-unstyled" href="/search?term='+b[0]+'" target="_blank">'+b[0]+"</a></span>":1<b.length?'\n        <span class="text-muted"><div class="dropdown" style="display: inline-block;"><a class="dropdown-toggle link-unstyled" data-bs-toggle="dropdown" href="#">'+b[0]+'</a>\n        <ul class="dropdown-menu">'+d+"</ul></div></span>":""}</div></section>
        <div class="row image-group-padding" id="row${a.year}-${a.month}-${a.day}">
        <span style="display: none;" class="yearTaken">${a.year}</span>
        <span style="display: none;" class="monthTaken">${a.month}</span>
        <span style="display: none;" class="dayTaken">${a.day}</span>                    
        `}
    `}static TimelinePreLoadGalleryBody({metadata:a}){return`
        <div id="photoThumbnailContainer${a.id}" class="photo-thumbnail-container photo-thumbnail ${a.type.includes("video")?"is-video":"is-not-video"}" style="width:${a.thumbnailSmallWidth}px;height:${a.thumbnailSmallHeight}px;padding-left:0;padding-right:0;">
            <a class="lightGalleryIndexAnchor" id="lightGalleryIndex${a.id}"></a>
            <input type="hidden" name="filename${a.id}" id="filename${a.id}" value="${a.fileName}">
            <input type="hidden" name="thumbnailCentered${a.id}" id="thumbnailCentered${a.id}" value="${encodeURI(a.thumbnailUrlCentered)}">
            ${null==a.year||null==a.month||null==a.day?`
            <input type="hidden" name="thumbnailUrl-undated[]" id="thumbnailUrl_${a.id}" value="${encodeURI(a.thumbnailUrlSmall)}">
            <img loading="lazy" class="photo-thumbnail-image thumbnailTag_undated" id="image${a.id}" width="${a.thumbnailSmallWidth}" height="${a.thumbnailSmallHeight}">
            `:`
            <input type="hidden" name="thumbnailUrl-${a.year}-${a.month}-${a.day}[]" id="thumbnailUrl_${a.id}" value="${encodeURI(a.thumbnailUrlSmall)}">
            <img loading="lazy" class="photo-thumbnail-image thumbnailTag_${a.year}-${a.month}-${a.day}" id="image${a.id}" width="${a.thumbnailSmallWidth}" height="${a.thumbnailSmallHeight}">
            `}
            
            <div id="tntl${a.id}"></div>
            <div id="tnbr${a.id}"></div>
            <div id="tnbl${a.id}"></div>
            <div id="tntr${a.id}"></div>
            <div id="tncentered${a.id}"></div>
    
            <span id="metadatamodal${a.id}"></span>
        </div>
    `}static TimelinePreLoadGalleryFooter({metadata:a,lastDate:b}){return`
        ${null===a.year||null===a.month||null===a.day?'\n                <span class="scrollspy metadataprocessed" id="tail_undated"></span>\n            </div>\n        </span>\n        <span class="attachMetadataPhotos" id="amp_undated" style="visibility: hidden">EOL</span>\n        ':`
            ${b===a.year+"-"+a.month+"-"+a.day?`
                    <span class="scrollspy metadataprocessed" id="tail_${a.year}-${a.month}-${a.day}"></span>
                </div>
            </span>
            <span class="attachMetadataPhotos" id="amp_${a.year}-${a.month}-${a.day}" style="visibility: hidden">EOL</span>
            `:`
                    <span class="scrollspy metadataprocessed" id="tail_${a.year}-${a.month}-${a.day}"></span>
                </div>
            </span>
            <span class="attachMetadataPhotos" id="amp_${a.year}-${a.month}-${a.day}"></span>
            `}                       
        `}
    `}static TimelineGalleryBottomLeftOverlay({metadata:a,editIcon:b}){return`
        <a href="#" id="metadataModalEdit${a.id}" data-bs-target="#propTimelinModal">
            <span class="${b}" style="font-size: 1rem;color: lightgray;"></span>
        </a>
    `}static TimelineGalleryTopLeftOverlay({metadata:a}){return`
        <a href="#" id="select${a.id}">
            <span id="tlicon${a.id}" class="bi-circle" style="font-size: 1rem;color: lightgray;"></span>
        </a>
    `}static TimelineGalleryTopRightOverlay({metadata:a}){return`
        ${0<=a.type.indexOf("video")?`
            <span class="overlayIconBackground"><span id="duration${a.id}">${a.hasOwnProperty("duration")&&null!==a.duration&&""!==a.duration?a.duration:"0:00"}</span>&nbsp;<span id="video${a.id}" class="bi-camera-video overlayIcon" title="video"></span></span>
            `:` 
                ${null!==a.originalImageWidth&&null!==a.originalImageHeight&&a.originalImageWidth>2*a.originalImageHeight?`
                        <span id="panorama${a.id}" class="bi-aspect-ratio overlayIcon overlayIconBackground" title="panorama"></span>
                    `:`
                    ${"gif"===a.expectedExtension?`
                    <span id="gif${a.id}" class="bi-layers overlayIcon overlayIconBackground" title="gif"></span>
                    `:""}
                `}
            `}
    `}static TimelineGalleryBottomRightOverlay({metadata:a}){return`
        <a href="#" id="favorite${a.id}" class="text-decoration-none">
            <span class="overlayIconBackground">
                <span id="briconcount${a.id}"></span> <span id="bricon${a.id}" class="overlayIcon"></span>
            </span>
        </a>
    `}static TimelineGalleryCenterOverlay({metadata:a,mediaContent:b}){return`
        <a class="mediaLink" 
            id="mediaLink${a.id}"
            data-download-url="${0<=a.type.indexOf("video")?encodeURI(a.videoUrl):encodeURI(a.thumbnailUrlOriginal)}/download"
            data-metadataid="${a.id}"
            ${0<=a.type.indexOf("video")?`data-video="${Util.encodeHtml(b.video)}"`:`data-src="${encodeURI(a.thumbnailUrlOriginal)}"`}
            ${null!=a.description?`data-sub-html="${Util.encodeHtml(a.description)}"`:""}
    
            ${null!==a.originalImageWidth&&null!==a.originalImageHeight&&null!==a.thumbnailSmallWidth&&null!==a.thumbnailSmallHeight?`
            data-lg-size="${a.thumbnailSmallWidth}-${a.thumbnailSmallHeight}-${a.thumbnailSmallWidth},${a.originalImageWidth}-${a.originalImageHeight}"
            data-responsive="${encodeURI(a.thumbnailUrlSmall)} ${a.thumbnailSmallWidth}"
            data-thumb="${encodeURI(a.thumbnailUrlSmall)}"
            data-width="${a.originalImageWidth}"
            `:""}
            >
            <span class="${0<=a.type.indexOf("video")?"bi-play-btn":"bi-play-circle"}" style="font-size: 4rem;color: lightgray;"></span>
        </a>
    `}}
;
